package kz.zani.mobile

import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class TaskCreateParentTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun catalog()=JSONObject(fixture("task-create-parent-cases"))
    private val context=TaskDraftContext(101,1)
    private fun detail()=JsonContracts.taskDetails(fixture("task-101-1101"))
    private fun choice()=TaskDraftParentChoice.make(detail(),101,1101)!!
    private fun client()=TaskDraftClientChoice.make(JsonContracts.clientProfile(fixture("client-101-701")),101,701)!!
    private fun appointment()=TaskDraftAppointmentChoice.make(JsonContracts.detail(fixture("appointment-101-501")),101,501)!!
    private class Reads:TaskReadRepository {
        val calls=mutableListOf<String>();val lists=mutableListOf<CompletableDeferred<TaskPage>>();val details=mutableListOf<CompletableDeferred<TaskDetails>>()
        override suspend fun tasks(business:Int):TaskPage {calls+="list:$business";return CompletableDeferred<TaskPage>().also {lists+=it}.await()}
        override suspend fun taskDetails(business:Int,id:Int):TaskDetails {calls+="detail:$business:$id";return CompletableDeferred<TaskDetails>().also {details+=it}.await()}
    }
    private class Port:SyntheticTaskCreatePort {
        override val grants=listOf(SyntheticTaskCreateGrant(101,9001,true));val calls=mutableListOf<TaskCreateAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticTaskCreateOutcome>>()
        override suspend fun execute(attempt:TaskCreateAttempt):SyntheticTaskCreateOutcome {calls+=attempt;return CompletableDeferred<SyntheticTaskCreateOutcome>().also {pending+=it}.await()}
    }
    private fun repo()=APIReadRepository(ReadTransport {q->val b=q.query.getValue("business").toInt();when {
        q.path=="/api/mobile/v1/clients/"->FixtureClientSearch.list(fixture("client-search-catalogue-$b"),b,q.query["search"] ?: "")
        q.path.startsWith("/api/mobile/v1/clients/")->FixtureClientSearch.profile(fixture("client-search-catalogue-$b"),b,q.path.trimEnd('/').substringAfterLast('/').toInt())
        q.path=="/api/mobile/v1/appointments/"->ReadResponse(200,fixture("appointments-$b"))
        q.path.startsWith("/api/mobile/v1/appointments/")->ReadResponse(200,fixture("appointment-$b-${q.path.trimEnd('/').substringAfterLast('/')}"))
        else->error("Unexpected read in Parent reference flow: ${q.path}")
    }})
    private fun fill(m:TaskDraftModel) {m.bind(context);m.open(context);m.update(TaskDraftField.TITLE,"  Child task\n",m.inputControl);m.update(TaskDraftField.DESCRIPTION,"  Keep child raw notes\n",m.inputControl);m.chooseDue(TaskDraftDueMode.SET,m.inputControl);m.update(TaskDraftField.DUE_AT,"2026-11-02T09:30:00+05:00",m.inputControl);m.chooseReminder(TaskDraftDueMode.SET,m.inputControl);m.update(TaskDraftField.REMINDER_AT,"2026-11-01T14:00:00Z",m.inputControl)}
    private fun check(block:suspend TestScope.(TaskDraftModel,Port,Reads)->Unit)=runTest {val reads=Reads();val port=Port();val source=repo();val m=TaskDraftModel(port,this,source,source,reads);fill(m);try {block(m,port,reads)}finally {m.bind(null)}}
    private fun page(i:Int=0)=JsonContracts.tasks(catalog().getJSONArray("page_cases").getJSONObject(i).getString("page_json"))
    private fun TestScope.list(m:TaskDraftModel,r:Reads) {m.openParentPicker(m.inputControl);val read=m.parents!!;read.read(read.control);runCurrent();r.lists.last().complete(page());runCurrent()}
    private fun TestScope.select(m:TaskDraftModel,r:Reads) {list(m,r);val read=m.parents!!;read.open(1101,read.control);runCurrent();r.details.last().complete(detail());runCurrent();m.confirmParent(m.parentPickerOwner,read.control)}
    private fun TestScope.otherRelations(m:TaskDraftModel) {m.openClientPicker(m.inputControl);val owner=m.clientPickerOwner;val clients=m.clients!!;clients.submit(clients.control);runCurrent();clients.openClient(1754,clients.control);runCurrent();m.confirmClient(owner,clients.control);m.openAppointmentPicker(m.inputControl);val ao=m.appointmentPickerOwner;val read=m.appointments!!;read.updateDay("2026-10-28",read.control);read.read(read.control);runCurrent();read.open(501,read.control);runCurrent();m.confirmAppointment(ao,read.control);assertEquals(1754,m.state.values.client!!.id);assertEquals(501,m.state.values.appointment!!.id)}
    @Test fun sharedIdentityAndExactHeaderNoInheritedFieldsOrEligibilityRule() {val rows=catalog().getJSONArray("choice_cases");for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val d=JsonContracts.taskDetails(row.getString("detail_json"));val v=TaskDraftParentChoice.make(d,row.getInt("business"),row.getInt("id"));assertEquals(row.getString("name"),row.getBoolean("valid"),v!=null);if(v!=null){assertEquals(d.task.title,v.title);assertEquals(d.task.status,v.status);assertEquals(d.task.id,v.id)}}}
    @Test fun genericParentReceiptIndependentlyChecksAllThreeFksAndDoesNotAliasGet() {
        val rows=catalog().getJSONArray("receipt_cases");val auth=SyntheticTaskCreateGrant(101,9001,true).authorization(context)!!
        for(i in 0 until rows.length()) {val row=rows.getJSONObject(i);val s=TaskDraftSession();s.bind(context);s.open(context);val q=s.state.selection!!;s.update(TaskDraftField.TITLE,"Manual child",q);s.update(TaskDraftField.DESCRIPTION,"Original raw notes",q);s.chooseClient(client(),q);s.chooseAppointment(appointment(),q);if(!row.isNull("selected"))s.chooseParent(choice(),q);assertTrue(s.prepare(q));val ledger=TaskCreateAttemptLedger();val a=ledger.begin(s.state.review!!,auth)!!;val body=JSONObject(a.preparedBody()!!);assertFalse(body.has("parent_task_id"));assertEquals(!row.isNull("selected"),body.has("parent_task"));assertEquals(701,body.getInt("client"));assertEquals(501,body.getInt("appointment"));val read=TaskCreateParentRead.decode(row.getString("body_json"));assertEquals(when(row.getString("kind")){"parent"->TaskCreateParentRead.Parent(row.getInt("id"));"notSet"->TaskCreateParentRead.NotSet;else->TaskCreateParentRead.Unknown},read)
            val v=a.review.preview;val t=WorkTask(88001,v.title,"open",v.priority,null,business=101,description=v.description,createdBy=9001,createdAt="2026-10-30T12:00:00Z",updatedAt="2026-10-30T12:00:00Z");ledger.complete(a,SyntheticTaskCreateOutcome.Response(row.getInt("status"),t,clientRead=TaskCreateClientRead.Client(row.getInt("client_echo")),appointmentRead=TaskCreateAppointmentRead.Appointment(row.getInt("appointment_echo")),parentRead=read));val yes=row.getBoolean("accepted");assertEquals(row.getString("name"),yes,ledger.visible(auth)!!.phase==TaskCreateAttemptPhase.CONFIRMED);assertEquals(if(yes && !row.isNull("selected"))1101 else null,ledger.visible(auth)!!.parentTaskID);if(!yes){assertFalse(ledger.acknowledge(auth));assertNull(ledger.begin(a.review,auth));assertEquals(a.preparedBody(),ledger.records.single().attempt.preparedBody());assertEquals(a.review.values,ledger.records.single().attempt.review.values)}
        }
    }
    @Test fun foreignChoiceAndUnsentClearPreserveClientAppointmentAndRawDates() {val s=TaskDraftSession();s.bind(context);s.open(context);val q=s.state.selection!!;s.update(TaskDraftField.TITLE,"Raw child",q);s.update(TaskDraftField.DESCRIPTION,"Raw description",q);s.chooseClient(client(),q);s.chooseAppointment(appointment(),q);s.chooseDue(TaskDraftDueMode.SET,q);s.update(TaskDraftField.DUE_AT,"2026-11-02T09:30:00+05:00",q);s.chooseParent(choice(),q);val before=s.state.values;s.chooseParent(TaskDraftParentChoice.make(JsonContracts.taskDetails(fixture("task-202-1201")),202,1201),q);assertEquals(before,s.state.values);s.chooseParent(null,q);assertEquals(before.copy(parentTask=null),s.state.values);s.prepare(q);val a=TaskCreateAttemptLedger().begin(s.state.review!!,SyntheticTaskCreateGrant(101,9001,true).authorization(context)!!)!!;assertFalse(JSONObject(a.preparedBody()!!).has("parent_task"))}
    @Test fun noAutomaticReadOrDefaultAndOldParentInputCallbacksInactive()=check {m,_,r->val raw=m.state.values;val input=m.inputControl;val control=m.control;m.openParentPicker(input);assertTrue(r.calls.isEmpty());assertTrue(m.parents!!.state.items.isEmpty());assertNull(m.inputControl);m.update(TaskDraftField.TITLE,"overwrite",input);m.prepare(control);m.openClientPicker(input);m.openAppointmentPicker(input);assertEquals(raw,m.state.values);assertNull(m.clientPickerOwner);assertNull(m.appointmentPickerOwner)}
    @Test fun sourceListScopeCountCapAndUniquenessAreNotLocallyFiltered()=check {m,_,r->m.openParentPicker(m.inputControl);val read=m.parents!!;val rows=catalog().getJSONArray("page_cases");for(i in 0 until rows.length()){read.read(read.control);runCurrent();val pending=read.control;r.lists.last().complete(page(i));runCurrent();val yes=rows.getJSONObject(i).getBoolean("valid");assertEquals(rows.getJSONObject(i).getString("name"),yes,read.state.loaded);assertNotEquals(pending,read.control);if(yes){assertEquals(page(i).items,read.state.items);assertEquals(page(i).total,read.state.total);assertEquals(page(i).total>page(i).items.size,read.state.partial)}}}
    @Test fun currentWindowAndCompletedIndependentDetailRequired()=check {m,_,r->list(m,r);val read=m.parents!!;read.open(999999,read.control);assertNull(read.state.selectedID);read.open(1101,read.control);runCurrent();val pending=read.control;m.confirmParent(m.parentPickerOwner,pending);assertNull(m.state.values.parentTask);r.details.last().complete(detail());runCurrent();m.confirmParent(m.parentPickerOwner,pending);assertNull(m.state.values.parentTask);m.confirmParent(m.parentPickerOwner,read.control);assertEquals(1101,m.state.values.parentTask!!.id)}
    @Test fun closeAndReopenRejectLateListAndOldOwnerConfirmation()=check {m,_,r->val raw=m.state.values;m.openParentPicker(m.inputControl);val owner=m.parentPickerOwner;val read=m.parents!!;read.read(read.control);runCurrent();val old=read.control;m.closeParentPicker(owner);m.openParentPicker(m.inputControl);r.lists.last().complete(page());runCurrent();m.confirmParent(owner,old);assertEquals(raw,m.state.values);assertFalse(read.state.loaded)}
    @Test fun backRejectsLateDetailAndKeepsOnlyCurrentSuppliedWindow()=check {m,_,r->list(m,r);val read=m.parents!!;read.open(1101,read.control);runCurrent();read.backDetail(read.control);val current=read.control;r.details.last().complete(detail());runCurrent();assertEquals(current,read.control);assertNull(read.state.detail);assertTrue(read.state.loaded)}
    @Test fun foreignAndDeniedReadThenExplicitRetryNeedsReadyControl()=check {m,_,r->list(m,r);val read=m.parents!!;read.open(1101,read.control);runCurrent();r.details.last().complete(JsonContracts.taskDetails(fixture("task-202-1201")));runCurrent();assertEquals(ReadProblem.INVALID_PAYLOAD,read.state.problem);read.retryDetail(read.control);runCurrent();r.details.last().completeExceptionally(ReadException(ReadProblem.DENIED));runCurrent();assertEquals(ReadProblem.DENIED,read.state.problem);read.retryDetail(read.control);runCurrent();val old=read.control;r.details.last().complete(detail());runCurrent();m.confirmParent(m.parentPickerOwner,old);assertNull(m.state.values.parentTask);m.confirmParent(m.parentPickerOwner,read.control);assertEquals(1101,m.state.values.parentTask!!.id)}
    @Test fun parentChoiceRemovalRetainsPreviouslyChosenClientAppointmentAndEveryRawField()=check {m,_,r->otherRelations(m);val raw=m.state.values;select(m,r);assertEquals(raw.copy(parentTask=choice()),m.state.values);m.clearParent(m.inputControl);assertEquals(raw,m.state.values)}
    @Test fun unknownKeepsAllThreeChoicesRawBodyAttemptAndSameBusinessEpochGuard()=check {m,p,r->otherRelations(m);select(m,r);val input=m.inputControl;m.prepare(m.control);val review=m.state.review!!;m.launchSubmit(review,m.control);runCurrent();val a=p.calls.single();val body=a.preparedBody();p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();m.clearParent(input);m.openParentPicker(input);m.discard(review.selection);assertEquals(review.values,m.state.values);assertEquals(body,m.submission!!.attempt.preparedBody());assertEquals(TaskCreateAttemptPhase.UNKNOWN,m.submission!!.phase);m.bind(TaskDraftContext(101,2));m.open(TaskDraftContext(101,2));assertTrue(m.submissionBlocked);assertNull(m.submission);assertEquals(1,m.retainedAttemptCount);assertEquals(1,p.calls.size)}
    @Test fun changedBusinessRejectsPendingParentRead()=check {m,_,r->list(m,r);val read=m.parents!!;val owner=m.parentPickerOwner;read.open(1101,read.control);runCurrent();val old=read.control;m.bind(TaskDraftContext(202,2));r.details.last().complete(detail());runCurrent();m.confirmParent(owner,old);assertNull(m.state.values.parentTask);assertNull(read.state.context)}
    @Test fun getReadDoesNotGrantCreate()=runTest {val reads=Reads();val m=TaskDraftModel(ownerScope=this,parents=reads);fill(m);select(m,reads);m.prepare(m.control);assertEquals(1101,m.state.review!!.preview.parentTaskID);assertFalse(m.canSubmit);m.bind(null)}
    @Test fun defaultNoScopeDoesNotInventReadOwner() {val m=TaskDraftModel(parents=Reads());fill(m);m.openParentPicker(m.inputControl);assertFalse(m.parentPickerAvailable);assertNull(m.parentPickerOwner)}
}
